{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "Table 4 categorizes outcomes into patient-related, provider-related, and healthcare system-related outcomes. Patient-Related Outcomes : Most studies (n = 11, 69%) reported improved clinical outcomes, including early diagnosis and identification of high-risk individuals, along with the identification of new predictors and risk factors. ... Provider-Related Outcomes : Improvements in provider performance measures, particularly diagnostic accuracy, sensitivity, and precision, were reported in four studies. ... System-Related Outcomes : Enhanced healthcare utilization was noted in three studies, as evidenced by improved numbers needed to screen (NNS) or detect (NND), leading to more efficient AF screening in primary care.",
      "reason": "The manuscript explicitly lists and defines outcome domains (patient-related, provider-related, and healthcare system-related) and gives specific examples for each domain."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "Study outcomes primarily reported AF incidence or prevalence over periods ranging from 6 months to 5 years.",
      "reason": "The time frame of measurement for outcomes is specified (6 months to 5 years)."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement was found indicating whether all results compatible with each outcome domain (e.g., all measures, time points, analyses) were sought."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "We specifically reported on the highest-performing AI systems in AF detection, whether their performance was achieved by an ML model alone or in combination with other tools, and compared it against control groups.",
      "reason": "The authors indicate they specifically reported on the highest-performing AI systems, which suggests a selection process for results; however, they do not fully describe a comprehensive process or criteria for selecting among compatible results across outcome domains."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No changes to outcome-domain inclusion, definitions, or importance are reported in the provided evidence, so this conditional reporting item does not apply."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No changes to the processes for selecting results within eligible outcome domains are reported in the provided evidence, so this conditional item does not apply."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "The primary outcome was the detection of undiagnosed AF; secondary outcomes examined impacts on patients, healthcare providers, and systems.",
      "reason": "The manuscript identifies the primary outcome (detection of undiagnosed AF) as the key outcome for interpreting conclusions; additionally, model discrimination is noted as a key metric in the methods (text_9), supporting prioritisation rationale."
    }
  ],
  "confidence": 80
}

{
  "item_id": "PRISMA_2020_10b",
  "elements": [
    {
      "element_id": "prisma_2020_10b_e1",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "Key categories extracted included study information (e.g., data source), participant details (e.g., population characteristics), outcomes (e.g., outcome type and blinding of assessment), candidate predictors (e.g., predictor type), model development (e.g., sample size, handling of missing data, and predictor selection), model performance (e.g., calibration, classification measures), and model evaluation (e.g., internal vs. external validation). In addition to these criteria, we captured further details on study design, such as the clinical question, ML method, control groups, intended use of results, validation processes, and clinical outcomes (e.g., patient-related, provider-related, and healthcare system-related). For each study, we also documented the final variables used to develop the ML models.",
      "reason": "The authors list and define multiple 'other variables' sought for extraction (study information, participant details, outcomes, candidate predictors, model development, performance, evaluation) and additional study design and outcome details, demonstrating that these variables were specified and documented."
    },
    {
      "element_id": "prisma_2020_10b_e2",
      "status": "PRESENT",
      "chunk_id": "text_28",
      "quote": "Regarding missing data, we recorded unreported items as 'not reported' or 'unclear' in our extraction sheet. Due to the extent and variability of missing data, we did not impute values or contact study authors but instead chose to retain these studies and highlight the issue as a gap and a limitation in the current literature.",
      "reason": "The authors explicitly describe how they handled missing or unclear information: marking items as 'not reported'/'unclear', not imputing or contacting authors, and retaining studies while highlighting missingness as a limitation."
    },
    {
      "element_id": "prisma_2020_10b_e3",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "We used the Checklist for Critical Appraisal and Data Extraction for Systematic Reviews of Prediction Modeling Studies (CHARMS) for data extraction (Moons et al., 2014).",
      "reason": "The authors cite the CHARMS checklist as the tool used to determine and structure which data items to collect for extraction."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_11",
